/// Whether a genuine scrollbar drag is at its measured start. A caller can
/// handle release before the scrollbar ends its drag, without observing layout.
pub fn dragging_scrollbar_at_start(&self) -> bool {
    self.list_state.is_scrollbar_dragging()
