}

/// Return the row at the top of the viewport and how far into it the list

/// Existing empty space after a mounted last row, bounded by the viewport.
/// A caller can retain this space when prepending into a short document.
pub fn unused_tail_space(&self) -> gpui::Pixels {
    let viewport = self.list_state.viewport_bounds();
    self.list_state.item_count().checked_sub(1)
        .and_then(|last| self.list_state.bounds_for_item(last))
        .map_or(px(0.), |last| (viewport.bottom() - last.bottom()).max(px(0.)).min(viewport.size.height))
}

