/// Native query input for capturing live value/preedit before navigation.
pub fn query_input(&self) -> Entity<InputState> { self.query_input.clone() }

/// Restore an immediate delegate query without selection/scroll resets.
pub fn restore_query(&mut self, query: &str, window: &mut Window, cx: &mut Context<Self>) {
    self._search_task = Task::ready(());
    self.deferred_scroll_to_index = None;
    let query = query.to_string();
    self.query_input.update(cx, |input,cx| input.set_value(query.clone(),window,cx));
    self.last_query = Some(query.trim().to_string());
    self.set_searching(false,window,cx);
    self._search_task = self.delegate.perform_search(query.trim(),window,cx);
    cx.notify();
}

/// Set the query text of the search input, this will trigger a search.

/// Restore an admitted anchor without manufacturing a user-scroll event.
pub fn restore_anchor(&mut self, index: usize, offset: gpui::Pixels, cx: &mut Context<Self>) -> bool {
    if index >= self.list_state.item_count() { return false; }
    self.disclosure_hold = true;
    self.list_state.set_follow_mode(FollowMode::Normal);
    self.list_state.scroll_to(ListOffset { item_ix:index, offset_in_item:offset });
    cx.notify(); true
}

