/// Refuse navigation during search preedit; otherwise retire this popup
/// and return focus to its mounted trigger before an app opens another layer.
pub fn prepare_navigation(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
    let input = self.state.list.read(cx).query_input();
    if input.update(cx, |input, cx| gpui::EntityInputHandler::marked_text_range(input, window, cx).is_some()) {
        return false;
    }
    if self.state.open {
        self.clear_query_and_restore_cursor(window, cx);
        self.set_open(false, cx);
        self.focus(window, cx);
    }
    true
}

